function p6Stack(counts){const total=Object.values(counts).reduce((sum,value)=>sum+value,0)||1;return `<div class="p6Stack" aria-label="Distribución por estado">${Object.entries(P6_STATUS).map(([key,status])=>`<i class="${key}" title="${status.label}: ${counts[key]||0}" style="--state:${status.color};width:${(counts[key]||0)/total*100}%"></i>`).join('')}</div>`;}
