async function loadPatioOverview(focus=true){
 if(!isUrban()||!urbanScene?.ensureIfcSection)return null;
 const activeScene=urbanScene;
 if(!patioOverviewPromise){
  toast(state.lang==='en'?'Loading complete depot 102–112…':'Cargando Patio Taller completo 102–112…');
  patioOverviewPromise=Promise.allSettled(patioSections.map(section=>activeScene.ensureIfcSection(section))).then(results=>{
   const box=new THREE.Box3();let loaded=0;
   results.forEach(result=>{if(result.status==='fulfilled'){box.union(result.value);loaded++;}});
   return {box,loaded};
  }).catch(error=>{patioOverviewPromise=null;throw error;});
 }
 const result=await patioOverviewPromise;
 if(urbanScene!==activeScene||!isUrban()||result.box.isEmpty())return result;
 if(activeIfcFocus){applyIfcFocus(activeScene,activeIfcFocus);return result;}
 applyIfcFocus(activeScene,null);
 if(focus)fitPatioOverview(result.box);
 toast(state.lang==='en'?`${result.loaded} depot sections visible`:`${result.loaded} secciones del Patio Taller visibles`);
 return result;
}
