async function buildTrackingStation(targetRoot,view,code){
 $('#app').dataset.stationModel='loading';toast('Cargando modelo IFC '+code+'…');
 await urbanLoad;if(root!==targetRoot||state.view!==view||activeStation.code!==code)return;
 if(!urbanAssets){$('#app').dataset.stationModel='error';toast('No se pudo cargar el modelo de '+code);return;}
 const modelScene=buildUrbanMap(targetRoot,urbanAssets,label,selectInfo,openProgressActions,false,false,code);urbanScene=modelScene;
 try{
  const bounds=await modelScene.ensureIfcSection(code);
  if(root!==targetRoot||urbanScene!==modelScene||state.view!==view||activeStation.code!==code)return;
  modelScene.isolateSection(code);stationModelBounds=bounds.clone();stationSceneReady=true;if(stationViews.has(view)){stationControls=createStationModelControls(targetRoot,modelScene.sectionDefinitions.get(code),code,bounds);modelScene.pickProgressElement=stationControls.pick;applyFloors();stationControls.setAlarm(state.alarm);}
  $('#app').dataset.stationModel=code;$('#aerialCredit').hidden=true;
  if(view==='railway'||view==='maintenance')buildStationTrain(targetRoot,code,bounds);
  fitStationModel(true);renderToolbar();updateBadge();
 }catch(error){if(root!==targetRoot)return;$('#app').dataset.stationModel='error';toast('Modelo IFC de '+code+' no disponible');}
}
function buildStationTrain(targetRoot,code,bounds){
 const station=urbanAssets.data.stations.find(s=>s.code===code),center=bounds.getCenter(new THREE.Vector3());
 const reference=station?.center?new THREE.Vector3(station.center[0]*.06,0,-station.center[1]*.06):center.clone();
 const paths=urbanAssets.data.route.type==='LineString'?[urbanAssets.data.route.coordinates]:urbanAssets.data.route.coordinates;
 let closest=null;
 for(const path of paths)for(let i=1;i<path.length;i++){
  const a=new THREE.Vector3(path[i-1][0]*.06,0,-path[i-1][1]*.06),b=new THREE.Vector3(path[i][0]*.06,0,-path[i][1]*.06),ab=b.clone().sub(a);
  if(!ab.lengthSq())continue;const t=THREE.MathUtils.clamp(reference.clone().sub(a).dot(ab)/ab.lengthSq(),0,1),p=a.clone().addScaledVector(ab,t),distance=p.distanceToSquared(reference);
  if(!closest||distance<closest.distance)closest={distance,p,direction:ab.normalize()};
 }
 const direction=closest?.direction||new THREE.Vector3(0,0,1),base=closest?.p||reference;
 // Track level is read from the station's physical IFC rails where available.
 const entry=modelSceneEntry(code),railBounds=new THREE.Box3();
 entry?.group.traverse(object=>{if(object.isMesh&&/rail|riel|carril|via ferrovi|track/i.test(object.name))railBounds.union(new THREE.Box3().setFromObject(object));});
 base.y=railBounds.isEmpty()?(urbanAssets.placement.streetHeightInScene??.24)+.72:railBounds.max.y;
 const normal=new THREE.Vector3(direction.z,0,-direction.x);base.addScaledVector(normal,.18);
 railTrain=new THREE.Group();targetRoot.add(railTrain);const carLength=1.95,gap=.11,total=6*carLength+5*gap;
 for(let index=0;index<6;index++){const car=createMetroTrainCar(carLength,{kind:'train',id:'G102 / '+String(index+1).padStart(2,'0'),station:code},register,doors);car.position.x=-total/2+carLength/2+index*(carLength+gap);if(index===5)car.rotation.y=Math.PI;railTrain.add(car);}
 railTrain.rotation.y=-Math.atan2(direction.z,direction.x)+Math.PI;railTrain.position.copy(base);
 const trainLabel=label(base.clone().add(new THREE.Vector3(0,1.2,0)).toArray(),()=>'<em>▰</em> G102 · '+(state.paused?'0':'72')+' km/h',()=>selectInfo({kind:'train',id:'G102'}));
 stationRailMotion={base:base.clone(),direction,range:Math.max(5,Math.max(bounds.getSize(new THREE.Vector3()).x,bounds.getSize(new THREE.Vector3()).z)),label:trainLabel};
}
function modelSceneEntry(code){return urbanScene?.sectionDefinitions.get(code);}

