const povInputs=new Set(),povVelocity=new THREE.Vector3(),povForward=new THREE.Vector3(0,0,-1),povRight=new THREE.Vector3(),povDesired=new THREE.Vector3(),povEuler=new THREE.Euler(0,0,0,'YXZ');
