function updatePovUi(){const controlsEl=$('#povControls');if(!controlsEl)return;const en=state.lang==='en';const captions={move:en?'Movement joystick':'Joystick de movimiento',height:en?'Height':'Altura',look:en?'View joystick':'Joystick de mirada',pivot:povMode?(en?'Pivot centered in POV':'Pivote centrado en el POV'):(en?'Drag a joystick to enter POV':'Arrastra un joystick para entrar al POV')};$$('[data-pov-caption]').forEach(el=>el.textContent=captions[el.dataset.povCaption]||'');const names={forward:en?'Move forward':'Avanzar',backward:en?'Move backward':'Retroceder',strafeLeft:en?'Move left':'Mover a la izquierda',strafeRight:en?'Move right':'Mover a la derecha',ascend:en?'Move up':'Subir',descend:en?'Move down':'Bajar',turnLeft:en?'Turn left':'Girar a la izquierda',turnRight:en?'Turn right':'Girar a la derecha',lookUp:en?'Look up':'Mirar arriba',lookDown:en?'Look down':'Mirar abajo'};$$('[data-pov-action]').forEach(button=>{button.title=names[button.dataset.povAction];button.setAttribute('aria-label',names[button.dataset.povAction])});$$('[data-pov-stick]').forEach(stick=>{const isMove=stick.dataset.povStick==='move';stick.title=en?(isMove?'Drag to move':'Drag to look'):(isMove?'Arrastra para desplazarte':'Arrastra para mirar');stick.setAttribute('aria-label',stick.title)});$('#povExit').textContent=povMode?(en?'Exit POV':'Salir de POV'):(en?'Activate POV':'Activar POV');}
