function setPovMode(active,rerender=true){active=Boolean(active&&isUrban());povMode=active;povInputs.clear();resetPovSticks();povVelocity.set(0,0,0);if(active){walk=false;state.tour=false;tween=null;const direction=controls.target.clone().sub(camera.position),distance=direction.length();if(distance<1e-5)direction.set(0,0,-1);else direction.normalize();povPivotDistance=THREE.MathUtils.clamp(distance||8,2,18);povPitch=Math.asin(THREE.MathUtils.clamp(direction.y,-1,1));povYaw=Math.atan2(-direction.x,-direction.z);controls.enabled=false;syncPovTarget();}else{controls.enabled=true;}updateRenderQuality();$('#app').classList.toggle('povMode',active);$('#povControls').hidden=!isUrban();$('#povReticle').hidden=!active;updatePovUi();updateHint();if(rerender)renderToolbar();}
function movePovCamera(dt){const pressed=name=>povInputs.has(name),analogMove=povStickValues.move,analogLook=povStickValues.look;const turn=((pressed('turnRight')||keys.has('arrowright'))?1:0)-((pressed('turnLeft')||keys.has('arrowleft'))?1:0)+analogLook.x,tilt=((pressed('lookUp')||keys.has('arrowup'))?1:0)-((pressed('lookDown')||keys.has('arrowdown'))?1:0)-analogLook.y;povYaw-=turn*dt*1.18;povPitch=THREE.MathUtils.clamp(povPitch+tilt*dt*.92,-1.42,1.42);syncPovTarget();povRight.crossVectors(povForward,camera.up).normalize();povDesired.set(0,0,0);povDesired.addScaledVector(povForward,((pressed('forward')||keys.has('w'))?1:0)-((pressed('backward')||keys.has('s'))?1:0)-analogMove.y);povDesired.addScaledVector(povRight,((pressed('strafeRight')||keys.has('d'))?1:0)-((pressed('strafeLeft')||keys.has('a'))?1:0)+analogMove.x);povDesired.y+=((pressed('ascend')||keys.has('e'))?1:0)-((pressed('descend')||keys.has('q'))?1:0);const speed=THREE.MathUtils.clamp(povPivotDistance*.32,1.4,7),magnitude=Math.min(1,povDesired.length());if(povDesired.lengthSq())povDesired.normalize().multiplyScalar(speed*magnitude);povVelocity.lerp(povDesired,1-Math.exp(-7*dt));camera.position.addScaledVector(povVelocity,dt);camera.position.y=Math.max(.15,camera.position.y);syncPovTarget();}
